use crate::interpreter::{CoreInstance,CoreModule,CoreStepOutcome,StepControl,Value};
use semio_framework_value::{NativeEncodeControl,ValueRefusalKind,native_encoding::NativeEncodeProgress};

#[test]
fn physical_checkpoint_requires_original_admission_and_preserves_actual_machine(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let word=fixture["word"].as_str().unwrap().parse::<u64>().unwrap();let bytes=crate::owned_result_tests::scalar_module(word);let module=std::sync::Arc::new(CoreModule::parse(&bytes).unwrap());let instance=CoreInstance::instantiate(module.clone()).unwrap();let observed=std::cell::Cell::new(0);let mut observer=|_:NativeEncodeProgress|{observed.set(observed.get()+1);true};let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut control=NativeEncodeControl::new(fixture["originalMaximumBytes"].as_u64().unwrap()as usize,&mut observer);control.install_retirement_recipient(&mut recipient).unwrap();let checkpoint=instance.checkpoint_controlled(&mut control).unwrap();assert_eq!(control.owned_bytes(),checkpoint.len()+std::mem::size_of::<Option<Vec<u8>>>());assert_eq!(&checkpoint[..9],fixture["magic"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as u8).collect::<Vec<_>>());let boundaries=observed.get();let g=&fixture["retirement"];let grant=semio_framework_value::retained_clone::RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};while control.has_retirement_owner(){control.close_retirement_recipient(grant).unwrap();}drop(control);
    let mut resumed=CoreInstance::restore(module,&checkpoint).unwrap();resumed.begin_export("result",Vec::new()).unwrap();let actual=match resumed.step(100,StepControl::default()){CoreStepOutcome::Complete{values,..}=>values,other=>panic!("unexpected restored machine {other:?}")};let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let independent=wasmtime::Instance::new(&mut store,&module,&[]).unwrap().get_typed_func::<(),i64>(&mut store,"result").unwrap().call(&mut store,()).unwrap();assert_eq!(actual,vec![Value::I64(independent)]);
    let mut observer=|_:NativeEncodeProgress|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut control=NativeEncodeControl::new(fixture["zeroMaximumBytes"].as_u64().unwrap()as usize,&mut observer);control.install_retirement_recipient(&mut recipient).unwrap();assert_eq!(instance.checkpoint_controlled(&mut control).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(control.owned_bytes(),0);
    for canceled in 1..=boundaries{let mut count=0;let mut observer=|_:NativeEncodeProgress|{count+=1;count!=canceled};let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut control=NativeEncodeControl::new(4096,&mut observer);control.install_retirement_recipient(&mut recipient).unwrap();assert_eq!(instance.checkpoint_controlled(&mut control).unwrap_err().kind,ValueRefusalKind::Canceled);let wrapper=std::mem::size_of::<Option<Vec<u8>>>();assert!(control.owned_bytes()==0||control.owned_bytes()==wrapper||control.owned_bytes()==checkpoint.len()+wrapper);while control.has_retirement_owner(){control.close_retirement_recipient(grant).unwrap();}}
    println!("[DEBUG] Owned Core physical checkpoint: measuredBeforeAllocation=true exactOriginalCapacity=true zeroCeilingOwned=0 cancellationBoundaries={boundaries} restoredMachineMatchesIndependentWasmtime=true");
}
